<script lang="ts">
 import {refreshAll} from '$app/navigation';
 import {command,display} from '#lib/client/api.ts';
 import type {AppData,Row} from '#lib/client/types.ts';
 import Icon from './Icon.svelte';
 import Status from './Status.svelte';
 let {data}:{data:AppData}=$props();
 let counts:Record<string,string>=$state({}),reasons:Record<string,string>=$state({}),selected:Record<string,string>=$state({}),reviewReasons:Record<string,string>=$state({}),confirmed:Record<string,boolean>=$state({});
 let query=$state(''),busyId=$state(''),error=$state(''),notice=$state('');
 const active=$derived(data.detail?.status==='counting');
 const hideExpected=$derived(data.detail?.blind&&data.detail?.status!=='completed');
 const lines=$derived(data.related?.inventory_count_lines||data.related?.count_lines||data.related?.lines||[]);
 const visible=$derived(lines.filter(line=>!query||[line.name,line.stock_name,line.stock_item_name,line.number,line.stock_number,line.qr_token].some(value=>String(value||'').toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de')))));
 const conflicts=$derived(lines.filter(line=>line.status==='needs_review').length);
 const currentPage=$derived(Math.max(1,Number(data.summary?.inventoryCountPage??1)));
 const total=$derived(Number(data.summary?.inventoryCountTotal??lines.length));
 const pages=$derived(Math.max(1,Math.ceil(total/500)));
 function inputQuantity(value:unknown){return value===null||value===undefined?'':String(value).replace(/(\.\d*?[1-9])0+$|\.0+$/,'$1').replace('.',',');}
 function observations(line:Row){return(data.related?.count_observations||[]).filter(item=>item.line_id===line.id);}
 function person(item:Row){return item.actor_name&&!/^[a-f0-9-]{36}$/i.test(item.actor_name)?item.actor_name:'Berechtigter Mitarbeiter';}
 function quantity(value:unknown){return value===null||value===undefined||value===''?'Noch nicht erfasst':new Intl.NumberFormat('de-DE',{maximumFractionDigits:6}).format(Number(value));}
 async function save(line:Row,event:SubmitEvent){event.preventDefault();if(busyId||!active)return;busyId=line.id;error='';notice='';try{const result=await command('inventory.count.record',line.id,{counted_quantity:String(counts[line.id]??line.counted_quantity??''),reason:reasons[line.id]||undefined},line.version);notice=result.status==='needs_review'?'Der abweichende Zählbeleg wurde erhalten. Wählen und begründen Sie unten den tatsächlich bestätigten Zählstand. Der Abschluss bleibt bis zur Klärung gesperrt.':'Die Zählung wurde mit einem nachvollziehbaren Zählbeleg gespeichert.';delete counts[line.id];await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Zählung wurde nicht gespeichert. Prüfen Sie den aktuellen Stand.';}finally{busyId='';}}
 async function resolve(line:Row,event:SubmitEvent){event.preventDefault();if(busyId||!active||!confirmed[line.id])return;busyId=line.id;error='';notice='';try{await command('inventory.count.resolve',line.id,{observation_id:selected[line.id],reason:reviewReasons[line.id]},line.version);delete selected[line.id];delete reviewReasons[line.id];delete confirmed[line.id];delete counts[line.id];notice='Der ausgewählte tatsächliche Zählbeleg wurde mit Ihrer Begründung übernommen. Die übrigen Beobachtungen bleiben erhalten.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Klärung wurde nicht bestätigt. Ihre Eingaben bleiben erhalten.';}finally{busyId='';}}
</script>
<section class="panel"><header class="panel-header"><div><h2>{active?'Bestand zählen':'Dokumentierte Zählstände'}</h2><p>{hideExpected?'Blindzählung: Der Sollbestand bleibt bis zur abgeschlossenen Prüfung verborgen.':data.detail?.status==='completed'?'Die Zählung ist abgeschlossen. Bestätigter Zählstand, ursprünglicher Sollbestand und Belegverlauf bleiben nachvollziehbar.':'Gezählte Menge je Position erfassen. Differenzen werden erst beim ausdrücklichen Abschluss gebucht.'}</p></div><span class="count">{lines.length}</span></header><div class="panel-body">
 {#if error}<div class="notice error mb" role="alert">{error}</div>{/if}{#if notice}<div class="notice info mb" role="status">{notice}</div>{/if}
 {#if conflicts}<div class="notice warning mb"><div><strong>{conflicts===1?'Ein Zählstand muss geklärt werden':`${conflicts} Zählstände müssen geklärt werden`}</strong><p>Abweichende Beobachtungen bleiben erhalten. Wählen Sie je betroffener Position den tatsächlichen Zählbeleg mit einer konkreten Begründung. Vorher ist kein Abschluss möglich.</p></div></div>{/if}
 <div class="search-field mb"><Icon name="search" size={17}/><label class="sr-only" for="inventory-search">Artikel oder Kurznummer suchen</label><input id="inventory-search" bind:value={query} placeholder="Artikel, Kurznummer oder QR-Referenz"/></div>
 {#each visible as line(line.id)}<article class="inventory-item"><form class="inventory-line" onsubmit={event=>save(line,event)}><div class="inventory-line-title"><h3>{line.name||line.stock_name||line.stock_item_name||'Bestandsartikel'}</h3><p>{line.number||line.stock_number||'Bestandsartikel'}{!hideExpected&&line.expected_quantity!==undefined?` · Soll: ${quantity(line.expected_quantity)} ${display(line.unit)}`:''}</p><Status value={line.status}/></div><div class="field"><label for={`count-${line.id}`}>Gezählt · {display(line.unit)} *</label><input id={`count-${line.id}`} inputmode="decimal" value={counts[line.id]??inputQuantity(line.counted_quantity)} oninput={event=>counts[line.id]=event.currentTarget.value} pattern={'[0-9]+([,.][0-9]{1,6})?'} required disabled={!active||!!busyId}/><span class="field-help">Auch null bewusst eintragen.</span></div><div class="field"><label for={`count-reason-${line.id}`}>Zustand / Grund</label><input id={`count-reason-${line.id}`} bind:value={reasons[line.id]} disabled={!active||!!busyId}/></div>{#if active}<button class="btn primary" disabled={!!busyId} type="submit">{busyId===line.id?'Wird gespeichert …':'Zählbeleg speichern'}</button>{/if}</form>
 {#if line.status==='needs_review'&&active}<form class="count-review" onsubmit={event=>resolve(line,event)}><h4>Abweichende Zählbelege prüfen</h4><div class="field mt"><label for={`count-observation-${line.id}`}>Tatsächlich bestätigter Zählbeleg *</label><select id={`count-observation-${line.id}`} bind:value={selected[line.id]} required disabled={!!busyId}><option value="">Konkreten Zählbeleg auswählen</option>{#each observations(line) as item}<option value={item.id}>{quantity(item.quantity)} {display(line.unit)} · {person(item)} · {display(item.observed_at,'created_at')}</option>{/each}</select><span class="field-help">Wählen Sie einen vorhandenen Originalbeleg. Eine neue Beobachtung erfassen Sie oben; alte Einträge werden nicht überschrieben.</span></div><div class="field mt"><label for={`count-review-${line.id}`}>Warum ist dieser Zählstand richtig? *</label><textarea id={`count-review-${line.id}`} bind:value={reviewReasons[line.id]} required minlength="10" maxlength="3000" rows="3" disabled={!!busyId} placeholder="Zum Beispiel: gemeinsam erneut gezählt, ausgewählte Menge am gekennzeichneten Lagerort bestätigt."></textarea></div><label class="check-field mt"><input type="checkbox" bind:checked={confirmed[line.id]} required disabled={!!busyId}/><span>Ich habe den ausgewählten Zählbeleg und die tatsächliche Menge geprüft und möchte genau diesen Stand übernehmen.</span></label><button class="btn mt" disabled={!!busyId||!selected[line.id]||!confirmed[line.id]}>Geprüften Zählbeleg übernehmen</button></form>{/if}
 {#if observations(line).length}<details class="count-history"><summary>Zählbelege und Herkunft ansehen · {observations(line).length}</summary>{#each observations(line) as item}<div class="count-observation"><strong>{quantity(item.quantity)} {display(line.unit)}</strong><p>{person(item)} · {display(item.observed_at,'created_at')}</p>{#if item.notes}<p>{item.notes}</p>{/if}{#if line.resolved_observation_id===item.id}<p class="field-help">Für diesen Stand ausdrücklich übernommen.</p>{/if}</div>{/each}</details>{/if}
 </article>{/each}
 {#if !lines.length}<div class="empty-state compact"><div class="empty-icon"><Icon name="box"/></div><h3>Noch keine Zählpositionen</h3><p>Fixieren Sie zuerst den Sollbestand über den vorgesehenen Arbeitsschritt. Danach erscheinen die Bestände des gewählten Lagerbereichs.</p></div>{:else if !visible.length}<p class="field-help mt">Kein Artikel entspricht der Suche. Ändern oder leeren Sie den Suchtext.</p>{/if}
 {#if pages>1}<nav class="inventory-pagination mt" aria-label="Weitere Zählpositionen">{#if currentPage>1}<a class="btn" href={`?count_page=${currentPage-1}`}><Icon name="back" size={15}/>Vorherige 500</a>{/if}<p class="field-help">Seite {currentPage} von {pages} · {total} Positionen insgesamt. Die Suche oben betrifft die sichtbare Seite.</p>{#if currentPage<pages}<a class="btn" href={`?count_page=${currentPage+1}`}>Nächste 500<Icon name="arrow" size={15}/></a>{/if}</nav>{/if}<div class="inventory-location mt"><p class="field-help">Lagerplätze eindeutig benennen, damit Zählbelege nachvollziehbar bleiben.</p><a class="text-link" href="/stock-locations">Lagerorte verwalten<Icon name="arrow" size={15}/></a></div>
</div></section>
<style>.inventory-pagination{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px}.inventory-pagination .btn{min-height:48px}.inventory-item{padding:23px 0;border-top:1px solid var(--line)}.inventory-line{display:grid;grid-template-columns:1.1fr minmax(130px,.6fr) 1fr auto;gap:18px;align-items:end}.inventory-line-title h3{font-size:14px;line-height:1.5}.inventory-line-title p{font-size:12px;margin:7px 0}.inventory-line-title :global(.status){margin-top:5px}.count-review{margin-top:22px;padding:22px;background:var(--wash);border:1px solid var(--line);border-radius:7px}.count-review h4{font-size:14px;font-weight:550}.count-history{margin-top:18px}.count-history>summary{font-size:12px;color:var(--forest);cursor:pointer;min-height:32px}.count-observation{padding:14px 0;border-top:1px solid var(--line)}.count-observation strong{font-size:14px;font-variant-numeric:tabular-nums}.count-observation p{font-size:12px;margin-top:6px;line-height:1.6}.inventory-location{border-top:1px solid var(--line);padding-top:20px}.inventory-location .text-link{margin-top:12px;display:inline-flex;gap:9px}@media(max-width:1100px){.inventory-line{grid-template-columns:1fr 1fr}.inventory-line-title{grid-column:1/-1}.inventory-line .btn{grid-column:1/-1}}@media(max-width:760px){.inventory-line{grid-template-columns:1fr;gap:16px}.inventory-line-title h3{font-size:15px}.inventory-line input{font-size:16px;min-height:48px}.count-review{padding:18px}.count-history>summary{font-size:13px;min-height:44px}.count-observation p{font-size:13px}.inventory-line .btn,.count-review .btn{min-height:48px}}</style>
